/**
 * @description Schema side of the guided setup: the editable fields of Integration Connections and Integration Events
 * with their help, the field paths offered for Payload Fields (the object's fields and its parents' fields one lookup
 * up, the format IntegrationHubPayloadPaths reads) and the objects offered for Related Object. Describes are DEFERRED.
 * @group Integration Hub
 */
public with sharing class IntegrationHubSetupSchema {

    /** @description Fields the editor may set on an Integration Event, in step order. */
    public static final List<String> EVENT_FIELDS = new List<String>{
        'Name', 'Event_Key__c', 'Direction__c', 'Connection__c', 'Related_Object__c', 'Active__c', 'Share_With_Related_Record__c',
        'Retention_Days__c', 'Description__c', 'Path__c', 'Http_Method__c', 'Payload_Source__c', 'Payload_Fields__c',
        'Payload_Class__c', 'Transaction_Id_Key__c', 'Handler_Class__c', 'Expects_Callback__c', 'Callback_Timeout_Hours__c',
        'Response_Handler_Class__c', 'Business_Data_In_Response__c', 'Auto_Retry_Max__c', 'Retry_After_Minutes__c'
    };
    /** @description Fields the editor may set on an Integration Connection, in step order. */
    public static final List<String> CONNECTION_FIELDS = new List<String>{
        'Name', 'Description__c', 'Active__c', 'Named_Credential__c', 'Connection_Type__c', 'Auth_Class__c', 'Timeout_Seconds__c',
        'Headers__c', 'Inbound_User__c'
    };

    private static final Set<Schema.DisplayType> NOT_SENDABLE = new Set<Schema.DisplayType>{
        Schema.DisplayType.BASE64, Schema.DisplayType.ADDRESS, Schema.DisplayType.LOCATION
    };

    /**
     * @description The fields the editor may set.
     * @param objectName IH_Event__c or IH_Connection__c
     * @return the API names, in step order
     */
    public static List<String> editableFields(String objectName) {
        return objectName == IntegrationHubSetup.EVENT_OBJECT ? EVENT_FIELDS : CONNECTION_FIELDS;
    }

    /**
     * @description Label, help, type, required flag, default and picklist values of the editable fields.
     * @param objectName IH_Event__c or IH_Connection__c
     * @return the fields, in step order
     */
    public static List<IntegrationHubSetup.FieldInfo> fieldInfos(String objectName) {
        Map<String, Schema.SObjectField> all = describeOrNull(objectName).fields.getMap();
        List<IntegrationHubSetup.FieldInfo> infos = new List<IntegrationHubSetup.FieldInfo>();
        for (String api : editableFields(objectName)) {
            Schema.SObjectField f = all.get(api);
            if (f != null) {
                infos.add(info(f.getDescribe()));
            }
        }
        return infos;
    }

    /**
     * @description Field paths for Payload Fields: every field of the object (Subject) and, through each lookup, the
     * fields of the parent one level up (Account.Name). Polymorphic lookups (Owner) offer Name only. Binary, address and
     * location fields are left out.
     * @param objectName the related object
     * @return the paths
     */
    public static List<IntegrationHubSetup.FieldOption> fieldOptions(String objectName) {
        Schema.DescribeSObjectResult root = describeOrNull(objectName);
        if (root == null) {
            throw IntegrationHubPreview.auraError('Unknown object: ' + objectName + '. Enter the API name, e.g. Case.');
        }
        List<IntegrationHubSetup.FieldOption> out = new List<IntegrationHubSetup.FieldOption>();
        Map<Schema.SObjectType, Map<String, Schema.SObjectField>> parents = new Map<Schema.SObjectType, Map<String, Schema.SObjectField>>();
        for (Schema.SObjectField f : root.fields.getMap().values()) {
            Schema.DescribeFieldResult d = f.getDescribe();
            if (NOT_SENDABLE.contains(d.getType())) {
                continue;
            }
            out.add(new IntegrationHubSetup.FieldOption(d.getName(), d.getLabel()));
            if (d.getType() == Schema.DisplayType.REFERENCE && String.isNotBlank(d.getRelationshipName())) {
                out.addAll(parentOptions(d, parents));
            }
        }
        return out;
    }

    /**
     * @description Objects a trigger can publish, by label. Empty when the org does not answer the list (the screen then
     * takes the API name as text).
     * @return value = API name, label = object label, detail = "API name Voucher__c · Id prefix a0X"
     */
    public static List<IntegrationHubSetup.Option> objectOptions() {
        List<IntegrationHubSetup.Option> out = new List<IntegrationHubSetup.Option>();
        try {
            for (SObject row : IntegrationHubData.query('SELECT QualifiedApiName, Label, KeyPrefix FROM EntityDefinition '
                    + 'WHERE IsApexTriggerable = true AND IsQueryable = true LIMIT 2000', null)) {
                String api = (String) row.get('QualifiedApiName');
                out.add(new IntegrationHubSetup.Option(api, (String) row.get('Label'),
                    IntegrationHubSetupRecord.objectDetail(api, (String) row.get('KeyPrefix'))));
            }
        } catch (Exception e) {
            out.clear();
        }
        out.sort();
        return out;
    }

    /**
     * @description Describe of an object.
     * @param objectName the API name
     * @return the describe, or null when there is no such object
     */
    public static Schema.DescribeSObjectResult describeOrNull(String objectName) {
        if (String.isBlank(objectName)) {
            return null;
        }
        try {
            return Schema.describeSObjects(new List<String>{ objectName.trim() }, SObjectDescribeOptions.DEFERRED)[0];
        } catch (InvalidParameterValueException e) {
            return null;
        }
    }

    private static IntegrationHubSetup.FieldInfo info(Schema.DescribeFieldResult d) {
        IntegrationHubSetup.FieldInfo i = new IntegrationHubSetup.FieldInfo();
        i.apiName = d.getName();
        i.label = d.getLabel();
        i.help = d.getInlineHelpText();
        i.dataType = d.getType().name();
        i.length = d.getLength();
        i.required = !d.isNillable() && d.getType() != Schema.DisplayType.BOOLEAN;
        i.defaultValue = defaultOf(d);
        for (Schema.PicklistEntry p : d.getPicklistValues()) {
            if (p.isActive()) {
                i.options.add(new IntegrationHubSetup.Option(p.getValue(), p.getLabel(), null));
            }
        }
        return i;
    }

    private static String defaultOf(Schema.DescribeFieldResult d) {
        if (d.getType() == Schema.DisplayType.PICKLIST) {
            for (Schema.PicklistEntry p : d.getPicklistValues()) {
                if (p.isActive() && p.isDefaultValue()) {
                    return p.getValue();
                }
            }
            return null;
        }
        if (d.getType() == Schema.DisplayType.BOOLEAN) {
            return d.getDefaultValue() == null ? 'false' : String.valueOf(d.getDefaultValue());
        }
        String formula = d.getDefaultValueFormula();
        if (String.isBlank(formula)) {
            return null;
        }
        Boolean quoted = formula.length() >= 2 && formula.startsWith('"') && formula.endsWith('"');
        return quoted ? formula.substring(1, formula.length() - 1) : formula;
    }

    private static List<IntegrationHubSetup.FieldOption> parentOptions(Schema.DescribeFieldResult lookup,
            Map<Schema.SObjectType, Map<String, Schema.SObjectField>> cache) {
        List<IntegrationHubSetup.FieldOption> out = new List<IntegrationHubSetup.FieldOption>();
        List<Schema.SObjectType> targets = lookup.getReferenceTo();
        if (targets.isEmpty()) {
            return out;
        }
        String rel = lookup.getRelationshipName();
        String relLabel = lookup.getLabel().removeEndIgnoreCase(' ID').trim();
        // IntegrationHubPayloadPaths checks a path against the first target, as here.
        Map<String, Schema.SObjectField> parentFields = fieldsOf(targets[0], cache);
        if (targets.size() > 1) {
            // Polymorphic (Owner, What): only Name is safe in a query across the targets.
            if (parentFields.containsKey('name')) {
                out.add(parentField(rel, relLabel, parentFields.get('name').getDescribe()));
            }
            return out;
        }
        for (Schema.SObjectField f : parentFields.values()) {
            Schema.DescribeFieldResult d = f.getDescribe();
            if (!NOT_SENDABLE.contains(d.getType())) {
                out.add(parentField(rel, relLabel, d));
            }
        }
        return out;
    }

    private static IntegrationHubSetup.FieldOption parentField(String rel, String relLabel, Schema.DescribeFieldResult d) {
        IntegrationHubSetup.FieldOption o = new IntegrationHubSetup.FieldOption(rel + '.' + d.getName(), d.getLabel());
        o.parent = rel;
        o.parentLabel = relLabel;
        return o;
    }

    private static Map<String, Schema.SObjectField> fieldsOf(Schema.SObjectType objType,
            Map<Schema.SObjectType, Map<String, Schema.SObjectField>> cache) {
        if (!cache.containsKey(objType)) {
            cache.put(objType, objType.getDescribe(SObjectDescribeOptions.DEFERRED).fields.getMap());
        }
        return cache.get(objType);
    }
}
